const fs = require('fs');
const path = require('path');
const cp = require('child_process');

const ROOT = process.cwd();
const MOBILE = path.join(ROOT, 'mobile');
const SRC = path.join(MOBILE, 'src');

const screens = [
  path.join(SRC, 'screens', 'CollectionDetailsScreen.tsx'),
  path.join(SRC, 'screens', 'EntryFormScreen.tsx'),
  path.join(SRC, 'screens', 'TopicDetailsScreen.tsx'),
  path.join(SRC, 'screens', 'MemoryRadioScreen.tsx'),
];

for (const file of screens) {
  if (!fs.existsSync(file)) {
    throw new Error('SAFE STOP - missing ' + path.relative(ROOT, file));
  }
}

const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const backupDir = path.join(
  ROOT,
  '_recovery',
  'share-icon-v1-' + stamp,
);

fs.mkdirSync(backupDir, { recursive: true });

for (const file of screens) {
  fs.copyFileSync(
    file,
    path.join(backupDir, path.basename(file)),
  );
}

const assetDir = path.join(MOBILE, 'assets');
fs.mkdirSync(assetDir, { recursive: true });

const assetFile = path.join(
  assetDir,
  'ljingle-share-icon.png',
);

const shareIconBase64 = '';
fs.writeFileSync(
  assetFile,
  Buffer.from(shareIconBase64, 'base64'),
);

const glyphFile = path.join(
  SRC,
  'components',
  'ShareGlyph.tsx',
);

const glyphSource = `import {
  Image,
  StyleSheet,
  View,
} from 'react-native';

const shareArtwork = require(
  '../../assets/ljingle-share-icon.png',
);

type Props = {
  size?: number;
};

export function ShareGlyph({
  size = 28,
}: Props) {
  return (
    <View
      pointerEvents="none"
      style={[
        styles.crop,
        {
          width: size,
          height: size,
        },
      ]}
    >
      <Image
        resizeMode="contain"
        source={shareArtwork}
        style={{
          width: size * 2.35,
          height: size * 2.35,
        }}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  crop: {
    alignItems: 'center',
    justifyContent: 'center',
    overflow: 'hidden',
  },
});
`;

fs.writeFileSync(
  glyphFile,
  glyphSource,
  'utf8',
);

function read(file) {
  return fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n');
}

function write(file, text) {
  fs.writeFileSync(file, text, 'utf8');
}

function ensureImport(text) {
  if (
    text.includes(
      "from '../components/ShareGlyph'",
    )
  ) {
    return text;
  }

  const importMatches = [
    ...text.matchAll(/^import .*;$/gm),
  ];

  if (!importMatches.length) {
    throw new Error(
      'SAFE STOP - import block not found',
    );
  }

  const last =
    importMatches[importMatches.length - 1];
  const insertAt =
    last.index + last[0].length;

  return (
    text.slice(0, insertAt) +
    "\nimport { ShareGlyph } from '../components/ShareGlyph';" +
    text.slice(insertAt)
  );
}

function replaceShareArrow(text) {
  let next = text;

  next = next.replace(
    /<Text\s+style=\{styles\.portableShareText\}>\s*↗\s*<\/Text>/g,
    '<ShareGlyph />',
  );

  next = next.replace(
    /<Text\s+style=\{styles\.frequencyShareText\}>\s*↗\s*<\/Text>/g,
    '<ShareGlyph />',
  );

  return next;
}

for (const file of screens) {
  let text = read(file);

  const before = text;

  text = replaceShareArrow(text);

  if (text !== before) {
    text = ensureImport(text);
    write(file, text);
  }
}

const changedScreens = screens.filter((file) =>
  read(file).includes('<ShareGlyph />'),
);

if (changedScreens.length === 0) {
  throw new Error(
    'SAFE STOP - no portable share arrows found to replace',
  );
}

console.log('');
console.log('SHARE ICON V1 INSTALLED');
console.log('✓ your supplied artwork embedded as app asset');
console.log('✓ share no longer uses the ↗ link arrow');
console.log('✓ Collection share uses the new icon');
console.log('✓ Zapis share uses the new icon');
console.log('✓ Topic share uses the new icon');
console.log('✓ Frequency share uses the new icon');
console.log('✓ Link actions keep their existing link treatment');
console.log('BACKUP:', backupDir);
console.log('');

try {
  cp.execSync('npx tsc --noEmit', {
    cwd: MOBILE,
    stdio: 'inherit',
    shell: true,
  });

  console.log('');
  console.log('TYPESCRIPT CLEAN ✓');
} catch {
  console.error('');
  console.error('TYPESCRIPT HAS ERRORS');
  console.error('Backup:', backupDir);
  process.exitCode = 1;
}
